import{_ as e,o as n,c as s,a2 as o}from"./chunks/framework.D8Tso2Ul.js";const m=JSON.parse('{"title":"Módulo: Documentos","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/documentos.md","filePath":"modulos/documentos.md"}'),t={name:"modulos/documentos.md"};function d(i,a,c,l,r,p){return n(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="modulo-documentos" tabindex="-1">Módulo: Documentos <a class="header-anchor" href="#modulo-documentos" aria-label="Permalink to &quot;Módulo: Documentos&quot;">​</a></h1><p><strong>Ubicación:</strong> <code>Frontend/src/pages/Documents.tsx</code> · <code>Backend/handlers/documents/</code></p><p>Gestión centralizada de todos los documentos del sistema. Cada documento se clasifica en uno de dos tipos según su comportamiento: <strong>de obra</strong> o <strong>diario</strong>.</p><h2 id="clasificacion" tabindex="-1">Clasificación <a class="header-anchor" href="#clasificacion" aria-label="Permalink to &quot;Clasificación&quot;">​</a></h2><h3 id="documentos-de-obra-clasificacion-obra" tabindex="-1">Documentos de obra (<code>clasificacion: &quot;obra&quot;</code>) <a class="header-anchor" href="#documentos-de-obra-clasificacion-obra" aria-label="Permalink to &quot;Documentos de obra (\`clasificacion: &quot;obra&quot;\`)&quot;">​</a></h3><ul><li>Obligatorios por fase según el DS 44.</li><li>Se precrean al crear la obra (según <code>fasesConfig</code>).</li><li>Accesibles desde la zona central de documentos de la obra.</li><li>Cumplimiento agregado por fase (% completado).</li><li>No se asignan individualmente; son documentos de referencia que deben existir y estar firmados para cumplir normativa.</li></ul><h3 id="documentos-de-uso-diario-clasificacion-diario" tabindex="-1">Documentos de uso diario (<code>clasificacion: &quot;diario&quot;</code>) <a class="header-anchor" href="#documentos-de-uso-diario-clasificacion-diario" aria-label="Permalink to &quot;Documentos de uso diario (\`clasificacion: &quot;diario&quot;\`)&quot;">​</a></h3><ul><li>Se crean y asignan a personas específicas.</li><li>Al asignarse, el <code>EventBus</code> emite <code>document.assigned</code>, que genera una notificación en la bandeja de entrada de cada persona asignada.</li><li>Aparecen como pendientes en el dashboard del trabajador.</li><li>Requieren firma individual (PIN o presencial).</li><li>Tienen fecha límite opcional; si vencen, el estado pasa a <code>vencido</code>.</li></ul><h2 id="flujo-de-documento-de-obra" tabindex="-1">Flujo de documento de obra <a class="header-anchor" href="#flujo-de-documento-de-obra" aria-label="Permalink to &quot;Flujo de documento de obra&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Al crear la obra, se precrean los documentos obligatorios por fase</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>2. El prevencionista sube el archivo (PDF) a cada documento</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>3. Desde la zona central se ve el % de cumplimiento por fase</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>4. Al avanzar de fase, se verifica que los obligatorios estén firmados</span></span></code></pre></div><h2 id="flujo-de-documento-diario" tabindex="-1">Flujo de documento diario <a class="header-anchor" href="#flujo-de-documento-diario" aria-label="Permalink to &quot;Flujo de documento diario&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Prevencionista crea un documento con clasificacion &quot;diario&quot;</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>2. Lo asigna a una o más personas (POST /documents/{id}/assign)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>3. EventBus emite &quot;document.assigned&quot; → mensaje en InboxTable por persona</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>4. El trabajador ve la notificación en su bandeja de entrada</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>5. El trabajador firma el documento (PIN o presencial)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>6. El estado de la asignación cambia a &quot;firmado&quot;</span></span></code></pre></div><h2 id="estructura-de-un-documento" tabindex="-1">Estructura de un documento <a class="header-anchor" href="#estructura-de-un-documento" aria-label="Permalink to &quot;Estructura de un documento&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>documentoId    UUID</span></span>
<span class="line"><span>tenantId       FK</span></span>
<span class="line"><span>obraId         FK a la obra</span></span>
<span class="line"><span>clasificacion  obra | diario</span></span>
<span class="line"><span>fase           Solo si clasificacion=obra</span></span>
<span class="line"><span>tipoDS44       IRL | POLITICA_SSO | ENTREGA_EPP | MIPPER | ...</span></span>
<span class="line"><span>obligatorio    BOOL</span></span>
<span class="line"><span>titulo / descripcion / contenido</span></span>
<span class="line"><span>s3Key          tenants/{tenantId}/obras/{obraId}/docs/{key}</span></span>
<span class="line"><span>asignaciones   Lista de personas con estado de firma</span></span>
<span class="line"><span>firmas         Firmas recolectadas</span></span>
<span class="line"><span>estado         borrador | activo | completado | vencido</span></span></code></pre></div><h2 id="almacenamiento" tabindex="-1">Almacenamiento <a class="header-anchor" href="#almacenamiento" aria-label="Permalink to &quot;Almacenamiento&quot;">​</a></h2><p>Los archivos se guardan en S3 con aislamiento por prefijo de tenant:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hackaton-documents-{stage}/tenants/{tenantId}/obras/{obraId}/fase-{fase}/archivo.pdf</span></span></code></pre></div><p>La descarga se realiza mediante <strong>URLs prefirmadas (presigned)</strong> de S3, garantizando acceso seguro y temporal. Ver <a href="/manual/arquitectura/base-de-datos.html">Arquitectura · Base de datos</a>.</p><h2 id="endpoints-relacionados" tabindex="-1">Endpoints relacionados <a class="header-anchor" href="#endpoints-relacionados" aria-label="Permalink to &quot;Endpoints relacionados&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Método</th><th>Ruta</th><th>Acción</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/documents</code></td><td>Crear / subir documento</td></tr><tr><td><code>GET</code></td><td><code>/documents</code></td><td>Listar documentos</td></tr><tr><td><code>GET</code></td><td><code>/documents/{id}</code></td><td>Obtener documento</td></tr><tr><td><code>PUT</code></td><td><code>/documents/{id}</code></td><td>Actualizar metadatos</td></tr><tr><td><code>DELETE</code></td><td><code>/documents/{id}</code></td><td>Eliminar documento</td></tr><tr><td><code>POST</code></td><td><code>/documents/{id}/assign</code></td><td>Asignar a personas</td></tr><tr><td><code>GET</code></td><td><code>/documents/{id}/download</code></td><td>URL de descarga prefirmada</td></tr></tbody></table><p>Ver detalle en <a href="/manual/api/documentos.html">API · Documentos</a>.</p>`,21)])])}const h=e(t,[["render",d]]);export{m as __pageData,h as default};
